function validateComposition(v){if(v?.kind!=='bead-composition'||v.version!==1)throw Error('组合格式无效');dims(v.width,v.height);if(!Array.isArray(v.assets)||!Array.isArray(v.layers)||v.assets.length>100||v.layers.length>100)throw Error('素材或图层数量无效');let total=0;function pixels(p){dims(p.w,p.h);if(!Array.isArray(p.pixels)||p.pixels.length!==p.w*p.h||p.pixels.some(c=>c!==null&&(typeof c!=='string'||!/^#[0-9a-f]{6}$/i.test(c))))throw Error('素材像素无效');total+=p.pixels.length;if(total>1000000)throw Error('素材总像素超过一百万');return {name:typeof p.name==='string'?p.name.slice(0,60):'物品',w:p.w,h:p.h,pixels:p.pixels.slice()}}const assets=v.assets.map(pixels),layers=v.layers.map(l=>{if(!Number.isInteger(l.x)||!Number.isInteger(l.y)||Math.abs(l.x)>10000||Math.abs(l.y)>10000||!Number.isFinite(l.angle)||Math.abs(l.angle)>36000||!Number.isInteger(l.scale)||l.scale<1||l.scale>8)throw Error('图层变换无效');const angle=l.angle*Math.PI/180,tw=Math.ceil((Math.abs(l.w*Math.cos(angle))+Math.abs(l.h*Math.sin(angle)))*l.scale-1e-8),th=Math.ceil((Math.abs(l.w*Math.sin(angle))+Math.abs(l.h*Math.cos(angle)))*l.scale-1e-8);if(tw*th>1200000)throw Error('变换后的物品过大');return {...pixels(l),x:l.x,y:l.y,angle:l.angle,scale:l.scale,flipX:!!l.flipX,flipY:!!l.flipY,visible:l.visible!==false}});return {version:1,kind:'bead-composition',width:v.width,height:v.height,assets,layers}}
function transformObject(layer){const angle=(layer.angle%360)*Math.PI/180,cos=Math.cos(angle),sin=Math.sin(angle),scale=layer.scale||1,sw=layer.w*scale,sh=layer.h*scale,w=Math.max(1,Math.ceil(Math.abs(sw*cos)+Math.abs(sh*sin)-1e-8)),h=Math.max(1,Math.ceil(Math.abs(sw*sin)+Math.abs(sh*cos)-1e-8));if(w*h>1200000)throw Error('变换后的物品过大，请减小缩放');const pixels=Array(w*h).fill(null);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const dx=x+.5-w/2,dy=y+.5-h/2;let sx=Math.floor((dx*cos+dy*sin)/scale+layer.w/2),sy=Math.floor((-dx*sin+dy*cos)/scale+layer.h/2);if(sx<0||sy<0||sx>=layer.w||sy>=layer.h)continue;if(layer.flipX)sx=layer.w-1-sx;if(layer.flipY)sy=layer.h-1-sy;pixels[y*w+x]=layer.pixels[sy*layer.w+sx]}return {w,h,pixels}}
