function openComposition(){stop();if(!composition.layers.length){compositionCheckpoint();composition.width=state.width;composition.height=state.height;const patch=copyPatch({x:0,y:0,w:state.width,h:state.height});composition.layers=[{...patch,name:'当前帧底图',x:0,y:0,angle:0,scale:1,flipX:false,flipY:false,visible:true}];compositionSelected=0;}$('composer').showModal();compositionRender()}
