$('compositionNew').onclick=()=>{if(composition.layers.length&&!confirm('以当前帧重建组合？现有素材库保留，可撤销。'))return;compositionCheckpoint();const patch=copyPatch({x:0,y:0,w:state.width,h:state.height});composition.width=state.width;composition.height=state.height;composition.layers=[{...patch,name:'当前帧底图',x:0,y:0,angle:0,scale:1,flipX:false,flipY:false,visible:true}];compositionSelected=0;compositionRender();saveCompositionLocal()};
$('compositionClose').onclick=()=>{$('composer').close();compositionDrag=null};$('composer').addEventListener('cancel',()=>compositionDrag=null);
