$('layerFlipX').onclick=()=>editSelectedLayer(l=>l.flipX=!l.flipX);$('layerFlipY').onclick=()=>editSelectedLayer(l=>l.flipY=!l.flipY);$('layerRotateLeft').onclick=()=>editSelectedLayer(l=>l.angle=(l.angle-90)%360);$('layerRotateRight').onclick=()=>editSelectedLayer(l=>l.angle=(l.angle+90)%360);
