$('compositionApply').onclick=()=>{if(!composition.layers.length)return alert('请先把素材加入组合');if(state.width!==composition.width||state.height!==composition.height)return alert('请先将目标画布调整为 '+composition.width+' × '+composition.height+'，或用当前帧新建组合');if(!confirm('将组合结果替换当前作品的当前帧？可在主画布撤销，组合图层仍会保留。'))return;const pixels=composeObjects(composition),hexes=[...new Set(pixels.filter(Boolean))],used=new Set(state.palette.map(p=>p.code)),mapping=new Map(),additions=[];for(const hex of hexes){const p=state.palette.find(p=>p.hex.toLowerCase()===hex.toLowerCase());if(p){mapping.set(hex,p.code);continue}let n=1;while(used.has('L'+String(n).padStart(3,'0')))n++;const code='L'+String(n).padStart(3,'0');used.add(code);mapping.set(hex,code);additions.push({code,hex})}if(state.palette.length+additions.length>1000)return alert('合成后超过 1000 色，请先精简色卡');checkpoint();state.palette.push(...additions);state.frames[current]=pixels.map(p=>p===null?null:mapping.get(p));render();persist();$('composer').close()};

