$('assetUndo').onclick=()=>{if(assetHistory.length)assetDraft.pixels=assetHistory.pop();renderAssetEditor()};$('assetReset').onclick=()=>{assetHistory.push(assetDraft.pixels.slice());assetDraft=clone(assetOriginal);renderAssetEditor()};$('assetZoomIn').onclick=()=>{assetZoom=Math.min(30,assetZoom+2);renderAssetEditor()};$('assetZoomOut').onclick=()=>{assetZoom=Math.max(2,assetZoom-2);renderAssetEditor()};$('assetSave').onclick=()=>{compositionCheckpoint();const list=assetTarget.kind==='asset'?composition.assets:composition.layers;list[assetTarget.index]=clone(assetDraft);$('assetEditor').close();assetDraft=null;compositionRender();saveCompositionLocal()};$('assetCancel').onclick=()=>{$('assetEditor').close();assetDraft=null;assetDrawing=false};$('assetEditor').addEventListener('cancel',()=>{assetDraft=null;assetDrawing=false});
